private playCommonVideo(_videoType?: string): Promise<void> {
  return new Promise(resolve => {
    const { width, height } = this.cameras.main;
    this.clearUI();
    this.add.rectangle(width / 2, height / 2, width, height, 0x000000);

    const key = 'gacha';
    if (!this.cache.video.exists(key)) { resolve(); return; }

    const vid = this.add.video(width / 2, height / 2, key);
    vid.play(false);
    this.fitVideoToCanvas(vid, width, height);

    const doResolve = () => { if (vid.active) vid.destroy(); resolve(); };
    vid.on('complete', doResolve);
    this.time.delayedCall(12000, doResolve); // 12초 failsafe

    // 스킵 버튼: API 완료 시 즉시 스킵, 미완료 시 대기 후 자동 스킵
    const skipX = width - 37;
    const skipY = 28 + (height - 600) / 2;
    const skipBg = this.add.rectangle(skipX, skipY, 88, 30, 0x000000, 0.6).setInteractive();
    const skipTxt = this.add.text(skipX, skipY, 'SKIP  ▶▶', {
      fontSize: '12px', color: '#777777', fontFamily: 'monospace',
    }).setOrigin(0.5).setInteractive({ useHandCursor: true });
    skipTxt.on('pointerover', () => { if (skipTxt.active) skipTxt.setColor('#cccccc'); });
    skipTxt.on('pointerout',  () => { if (skipTxt.active) skipTxt.setColor('#777777'); });

    const onSkip = () => {
      if (this.videoSkipResolver !== null) return; // 이미 대기 중
      if (this.apiResultReady) {
        // API 응답 완료 → 즉시 스킵
        doResolve();
      } else {
        // API 미완료 → resolver 저장, UI를 "대기 중..." 으로 전환
        this.videoSkipResolver = doResolve;
        skipBg.disableInteractive();
        skipTxt.disableInteractive();
        skipTxt.setText('대기 중...');
        skipTxt.setColor('#ffaa44');
      }
    };
    skipBg.on('pointerdown', onSkip);
    skipTxt.on('pointerdown', onSkip);
  });
}

