    const gColor = GRADE_COLORS[pulled.grade] ?? 0xffffff;

    const { width: W, height: H } = this.cameras.main;
    const cx = W / 2;
    const yOff = (H - 600) / 2;

    // ── 배경: 사이버 우주 이미지 + 등급 컬러 헤이즈 ──
