      const bg = this.add.image(cx, H / 2, 'gacha_background');
      bg.setDisplaySize(W, H);
    } else {
      this.add.rectangle(cx, H / 2, W, H, 0x050510);
    }
    // 어두운 오버레이 (가독성 확보)
    this.add.rectangle(cx, H / 2, W, H, 0x000000, 0.5);
    // 등급 컬러 헤이즈 (중앙 중심 방사)
