    if (revealGradeKey) {
      const gradeImg = this.add.image(cx, 388 + yOff, revealGradeKey).setDisplaySize(52, 52).setOrigin(0.5).setAlpha(0);
      this.tweens.add({ targets: gradeImg, alpha: 1, duration: 300, delay: 400 });
