    this.time.delayedCall(700, () => {
      if (!this.scene.isActive()) return;

      let advanced = false;
      const advance = () => {
        if (advanced) return;
        advanced = true;
        this.input.off('pointerdown', advance);
        this.tweens.killAll();
        this.time.removeAllEvents();
        this.revealItemIndex++;
        this.showNextReveal();
      };

      this.input.on('pointerdown', advance);

